update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/maintenance-industrielle-orleans/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Orléans et dans le Loiret","mecanisme":"Le Loiret fait cohabiter deux mondes exigeants. D''un côté des plateformes logistiques branchées sur l''A10 et l''A71. De l''autre des ateliers de cosmétique et de pharmacie où chaque équipement doit rester qualifié. Le premier ne supporte pas l''arrêt, le second ne supporte pas l''intervention non documentée. Nous traitons les deux, avec des techniciens qui se déplacent partout en France.","cta":"Demander une intervention à Orléans","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option pour les nuits, les week-ends et les pics d''activité."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels et logisticiens en France, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats reçus passent l''entretien technique et comportemental, résultats partagés"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, et des techniciens mobiles partout en France"}]},{"type":"probleme","punchline":"Un trieur lâche en fin d''après-midi sur une plateforme du Loiret. Les commandes basculent au lendemain, et le client final ignore tout de votre panne mécanique.","puces":[{"accroche":"L''expédition du jour ne se rattrape pas.","texte":"Une heure perdue se paie en promesses rompues, pas en heures de main d''œuvre."},{"accroche":"Un équipement pharmaceutique non documenté redevient non conforme.","texte":"L''intervention sans trace écrite coûte une requalification."},{"accroche":"La Beauce impose son calendrier de récolte.","texte":"Stockage, séchage, manutention : le matériel doit être prêt quand la moisson arrive."},{"accroche":"Les allées restent pleines pendant que vous intervenez.","texte":"Préparateurs, caristes et techniciens partagent le même espace, et la coactivité se prépare."},{"accroche":"Le poste de maintenance vacant se voit sur la disponibilité machine.","texte":"Pas tout de suite, mais chaque semaine un peu plus."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Préventif calé sur vos heures de fonctionnement réelles","texte":", resserré avant les pics d''activité."},"benefice":"Vous entretenez au rythme du flux, pas au rythme d''un calendrier constructeur."},{"prestation":{"accroche":"Interventions en heures creuses","texte":"tôt le matin, entre deux équipes, de nuit selon le contrat."},"benefice":"Les opérations lourdes ne mangent jamais une vague de préparation."},{"prestation":{"accroche":"Traçabilité adaptée aux sites qualifiés","texte":"opérations documentées, pièces référencées, comptes rendus versés dans votre GMAO."},"benefice":"Votre qualité conserve la preuve sans la reconstruire après coup."},{"prestation":{"accroche":"Convoyage, tri et manutention pris dans leur ensemble","texte":"moto-réducteurs, rouleaux, bandes, capteurs, quais."},"benefice":"Un seul contrat du quai de réception au quai d''expédition."},{"prestation":{"accroche":"Couverture multi-technique","texte":"[mécanique](/expertises/mecanique/), [électrique](/expertises/electrique/), [automatisme](/expertises/automatisme/), [électromécanique](/expertises/electromecanique/), [hydraulique](/expertises/hydraulique/), [soudure](/expertises/soudure/)."},"benefice":"Une panne qui croise plusieurs métiers mobilise une seule équipe."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisation de techniciens mobiles partout en France."},"benefice":"Une panne du dimanche soir ne sacrifie pas le lundi matin."}],"prose":[{"texte":"Pour les entrepôts et plateformes, voir notre pratique de la [maintenance des équipements logistiques](/secteurs/logistique/). Les lignes alimentaires relèvent de la [maintenance en agroalimentaire](/secteurs/agroalimentaire/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez le cas","texte":"équipement, symptôme, criticité, contraintes d''accès et régime du site."},{"titre":"Nous vous rappelons dans l''heure","texte":"besoin qualifié, profil nommé, pièces à commander repérées."},{"titre":"Le chiffrage part avant le déplacement","texte":"périmètre, conditions de chantier, montant écrit."},{"titre":"L''intervention se cale sur vos règles de site","texte":"accueil sécurité, balisage, plan de prévention, consignation, puis diagnostic."},{"titre":"La cause racine est traitée après la remise en route","texte":"mesures, historique, récurrence par équipement."},{"titre":"Le compte rendu revient dans votre GMAO","texte":"constat, actions, pièces posées, récurrence relevée."}]},{"type":"garanties","puces":[{"accroche":"La mesure avant l''affirmation","texte":"disponibilité par zone, récurrence par équipement, respect du plan préventif. Vous jugez sur vos propres indicateurs."},{"accroche":"Le profil présenté avant l''arrivée","texte":"10 % des candidats retenus après entretien technique et comportemental, résultats d''évaluation partagés."},{"accroche":"Aucun délai de route inventé","texte":"rappel dans l''heure aux horaires ouvrés, astreinte 24/24 et 7/7 en option. Le reste tient à l''adresse du site, et il se dit avant d''engager."}]},{"type":"cta","question":"Besoin de savoir où votre site perd réellement de la capacité ?","bouton":"Demander une intervention à Orléans","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/maintenance-industrielle-orleans/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"10 à 20 techniciens une semaine sur deux, par créneaux de 8 heures, sur un centre logistique en continu","texte":"contrat annuel depuis septembre 2022","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"},{"titre":"Deux techniciens en poste sur site, dédiés à la maintenance curative des convoyeurs, trieurs et packaging","texte":"logistique et transport","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Six techniciens en permanence sur un contrat de préventif annuel, prise en charge complète réalisée en un mois","texte":"sites e-commerce, depuis septembre 2023","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Un responsable maintenance intégré sur site pendant une montée de cadence","texte":"pilotage repris sans rupture, troisième trimestre 2025","lienLibelle":"Étude de cas ERIKS","lienHref":"/preuves/eriks/"},{"titre":"Deux techniciens intégrés en 3x8 sur des lignes liquides et poudre","texte":"cadence continue, exigences d''hygiène strictes","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Orléans, alors que votre siège est à Lyon ?","reponse":"Oui. Nos techniciens se déplacent partout en France et interviennent sur site. Nos 4 agences sont Lyon (siège), Montréal, Dubaï et Madrid, et nous préférons l''annoncer plutôt que d''afficher une adresse orléanaise vide. Votre demande est rappelée dans l''heure aux horaires ouvrés. Sur votre site, la différence se fait sur le technicien qui arrive préparé, pas sur une plaque."},{"question":"Quelles communes couvrez-vous dans le Loiret ?","reponse":"Orléans et sa métropole, Saint-Jean-de-Braye, Fleury-les-Aubrais, Ingré, Chécy, Saran, Ormes, Saint-Cyr-en-Val. Puis le reste du Centre-Val de Loire vers Chartres, Blois et Bourges. Au-delà, le réseau national prend le relais."},{"question":"Intervenez-vous pendant l''exploitation, au milieu des préparateurs ?","reponse":"Oui, c''est le quotidien du secteur : plan de prévention, balisage, protection des personnes, coordination avec vos chefs d''équipe. Les opérations lourdes se planifient en heures creuses, les contrôles se font en marche quand l''équipement le permet."},{"question":"Travaillez-vous sur des lignes automatisées et des automates programmables ?","reponse":"Oui. Nos automaticiens interviennent sur SIEMENS et Schneider : diagnostic de programme, défauts intermittents, sauvegardes, supervision. Les cellules robotisées ABB et Fanuc entrent dans le même périmètre."},{"question":"Pouvez-vous couvrir plusieurs sites d''un même réseau ?","reponse":"Oui, avec un contrat unique, un interlocuteur, des comptes rendus au même format et un taux homogène. Le multi-sites logistique est l''un de nos terrains les plus fréquents."},{"question":"Combien coûte un contrat de préventif ?","reponse":"L''abonnement [Zéro arrêt](/offres/zero-arret/) est chiffré sur devis, engagement type 6 mois renouvelable. Préventif planifié, priorité en cas de panne, astreinte en option. Le périmètre s''écrit équipement par équipement, après un diagnostic gratuit."}]},{"type":"ctaFinal","question":"Besoin de fiabiliser vos flux avant la prochaine montée en charge ?","bouton":"Demander une intervention à Orléans","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/maintenance-industrielle-orleans/';
